// src/components/SvgFlow.js
import React, { useRef, useEffect } from "react";
import * as d3 from "d3";

function parseCodeToFlowchart(code = "") {
  const nodes = [];
  const edges = [];

  if (!code || !code.trim()) return { nodes, edges };

  // Parse function declaration
  const fnMatch = code.match(/function\s+(\w+)\s*\(([^)]*)\)/) || code.match(/const\s+(\w+)\s*=\s*\(([^)]*)\)\s*=>/);
  const fnName = fnMatch ? fnMatch[1] : "fn";
  const param = fnMatch ? fnMatch[2].trim() : "";

  // Start node
  nodes.push({ 
    id: "start", 
    label: "Start", 
    type: "terminal",
    shape: "stadium" 
  });

  // Function declaration node
  nodes.push({
    id: "function",
    label: `Function: ${fnName}(${param})`,
    type: "process",
    shape: "rectangle"
  });
  edges.push({ from: "start", to: "function" });

  // Input parameter node
  if (param) {
    nodes.push({ 
      id: "input", 
      label: `Input parameter: ${param}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ from: "function", to: "input" });
  }

  // Decision node for if condition
  const hasCondition = /if\s*\(/.test(code);
  if (hasCondition) {
    const condMatch = code.match(/if\s*\(([^)]+)\)/);
    const condition = condMatch ? condMatch[1].trim() : "condition";
    
    nodes.push({ 
      id: "decision", 
      label: `Check if ${condition}`, 
      type: "decision",
      shape: "diamond" 
    });
    edges.push({ 
      from: param ? "input" : "function", 
      to: "decision" 
    });

    // True path
    const trueLogMatch = code.match(/if\s*\([^{]*\)\s*{([^}]*)}/);
    const trueLog = trueLogMatch ? 
      trueLogMatch[1].trim().replace(/console\.log\(|\)/g, '').replace(/["']/g, '') : 
      "true branch";
    
    nodes.push({ 
      id: "true_process", 
      label: `Print: ${trueLog}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ 
      from: "decision", 
      to: "true_process", 
      label: "Yes" 
    });

    // False path
    const falseLogMatch = code.match(/else\s*{([^}]*)}/);
    const falseLog = falseLogMatch ? 
      falseLogMatch[1].trim().replace(/console\.log\(|\)/g, '').replace(/["']/g, '') : 
      "false branch";

    nodes.push({ 
      id: "false_process", 
      label: `Print: ${falseLog}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ 
      from: "decision", 
      to: "false_process", 
      label: "No" 
    });

    // Connect both paths to end
    edges.push({ from: "true_process", to: "end" });
    edges.push({ from: "false_process", to: "end" });
  } else {
    // If no condition, connect directly to end
    edges.push({ from: param ? "input" : "function", to: "end" });
  }

  // End node
  nodes.push({ 
    id: "end", 
    label: "End", 
    type: "terminal",
    shape: "stadium" 
  });

  return { nodes, edges };
}

function SvgFlow({ graph, code, onNodeClick }) {
  const svgRef = useRef();

  useEffect(() => {
    let g;
    
    // Use graph if provided, otherwise parse code
    if (graph && graph.nodes && graph.nodes.length) {
      g = graph;
      // Normalize the graph - ensure nodes have 'label' property
      g.nodes = g.nodes.map(node => ({
        ...node,
        label: node.label || node.text || 'Unknown',
        shape: node.shape || (
          node.type === 'decision' ? 'diamond' : 
          node.type === 'loop' ? 'diamond' :
          node.type === 'start' ? 'terminal' :
          node.type === 'end' ? 'terminal' :
          node.type === 'input' ? 'parallelogram' :
          node.type === 'output' ? 'parallelogram' :
          node.type === 'function' ? 'rectangle' :
          node.type === 'return' ? 'parallelogram' : 'rectangle'
        )
      }));
    } else if (code) {
      g = parseCodeToFlowchart(code);
    } else {
      g = { nodes: [], edges: [] };
    }
    
    const svgEl = d3.select(svgRef.current);
    svgEl.selectAll("*").remove(); // clear old diagram

    if (!g.nodes || !g.nodes.length) {
      // show placeholder text
      svgEl
        .append("text")
        .attr("x", 20)
        .attr("y", 30)
        .attr("fill", "#6b7280")
        .style("font-size", "14px")
        .text('No flowchart yet — click "Generate Flowchart"');
      return;
    }

    const width = Math.min(600, svgRef.current.parentElement?.clientWidth - 20 || 600);
    const nodeWidth = 200;
    const nodeHeight = 60;
    const verticalGap = 120;
    const horizontalGap = 280;

    const svgHeight = Math.max(400, g.nodes.length * verticalGap + 150);
    svgEl.attr("width", width).attr("height", svgHeight);
    svgEl.attr("viewBox", `0 0 ${width} ${svgHeight}`).attr("preserveAspectRatio", "xMidYMid meet");

    // Improved layout: detect branches
    const nodeMap = new Map(g.nodes.map(n => [n.id, n]));
    const visited = new Set();
    let yPosition = 80;
    
    // Function to layout nodes with branching
    const layoutNode = (nodeId, xPos, yPos, isLeftBranch = false, isRightBranch = false) => {
      if (visited.has(nodeId)) return yPos;
      
      const node = nodeMap.get(nodeId);
      if (!node) return yPos;
      
      visited.add(nodeId);
      node.x = xPos;
      node.y = yPos;
      
      // Ensure label exists
      if (!node.label && node.text) {
        node.label = node.text;
      }
      
      // Find outgoing edges
      const outgoingEdges = g.edges.filter(e => e.from === nodeId);
      
      // If this is a decision node with Yes/No branches
      if ((node.type === 'decision' || node.type === 'loop') && outgoingEdges.length >= 2) {
        const yesEdge = outgoingEdges.find(e => e.label === 'Yes' || e.label === 'True' || e.label === 'yes');
        const noEdge = outgoingEdges.find(e => e.label === 'No' || e.label === 'False' || e.label === 'no');
        
        let maxY = yPos + verticalGap;
        
        // Layout YES branch to the right
        if (yesEdge) {
          maxY = Math.max(maxY, layoutNode(yesEdge.to, xPos + horizontalGap / 2, yPos + verticalGap, false, true));
        }
        
        // Layout NO branch to the left
        if (noEdge) {
          maxY = Math.max(maxY, layoutNode(noEdge.to, xPos - horizontalGap / 2, yPos + verticalGap, true, false));
        }
        
        // Layout other edges (like loop back)
        const otherEdges = outgoingEdges.filter(e => e !== yesEdge && e !== noEdge);
        otherEdges.forEach(edge => {
          if (edge.label !== 'Loop back') {
            maxY = Math.max(maxY, layoutNode(edge.to, xPos, maxY + verticalGap));
          }
        });
        
        return maxY;
      } else if (outgoingEdges.length === 1) {
        // Single path - continue straight down or curve back to center
        const nextEdge = outgoingEdges[0];
        let nextX = xPos;
        
        // If we're in a branch, gradually move back to center
        if (isLeftBranch || isRightBranch) {
          nextX = xPos + (width / 2 - xPos) * 0.3; // Move 30% back towards center
        }
        
        return layoutNode(nextEdge.to, nextX, yPos + verticalGap);
      } else if (outgoingEdges.length === 0) {
        // End node
        return yPos + verticalGap;
      } else {
        // Multiple paths without labels
        let maxY = yPos + verticalGap;
        outgoingEdges.forEach((edge, idx) => {
          const offset = (idx - outgoingEdges.length / 2) * horizontalGap;
          maxY = Math.max(maxY, layoutNode(edge.to, xPos + offset, yPos + verticalGap));
        });
        return maxY;
      }
    };
    
    // Start layout from the first node (Start)
    if (g.nodes.length > 0) {
      layoutNode(g.nodes[0].id, width / 2, 80);
    }

    // markers for arrows
    svgEl
      .append("defs")
      .append("marker")
      .attr("id", "arrow")
      .attr("viewBox", "0 0 10 10")
      .attr("refX", 10)
      .attr("refY", 5)
      .attr("markerWidth", 7)
      .attr("markerHeight", 7)
      .attr("orient", "auto")
      .append("path")
      .attr("d", "M 0 0 L 10 5 L 0 10 z")
      .attr("fill", "#1e293b");

    // draw edges
    const edgeGroup = svgEl.append("g").attr("class", "edges");
    g.edges.forEach((e) => {
      const from = g.nodes.find((n) => n.id === e.from);
      const to = g.nodes.find((n) => n.id === e.to);
      if (!from || !to) return;

      const startX = from.x;
      const startY = from.y + nodeHeight / 2;
      const endX = to.x;
      const endY = to.y - nodeHeight / 2;

      let path;
      
      // If branching (significant horizontal difference), use curved path
      if (Math.abs(startX - endX) > 50) {
        // Curved path for branches
        const midY = (startY + endY) / 2;
        path = `M ${startX} ${startY} 
                C ${startX} ${midY} ${endX} ${midY} ${endX} ${endY}`;
      } else {
        // Straight vertical path
        path = `M ${startX} ${startY} 
                L ${endX} ${endY}`;
      }

      const pathElement = edgeGroup
        .append("path")
        .attr("d", path)
        .attr("fill", "none")
        .attr("stroke", "#1e293b")
        .attr("stroke-width", 2.5)
        .attr("marker-end", "url(#arrow)");

      if (e.label) {
        // Calculate label position along the path
        const labelX = (startX + endX) / 2;
        const labelY = (startY + endY) / 2;
        
        // Adjust label position for branching edges
        const offsetX = Math.abs(startX - endX) > 50 ? (endX - startX) * 0.15 : 0;
        
        // label with background
        const labelBg = edgeGroup
          .append("rect")
          .attr("x", labelX + offsetX - 22)
          .attr("y", labelY - 14)
          .attr("width", 44)
          .attr("height", 24)
          .attr("rx", 5)
          .attr("fill", "#ffffff")
          .attr("stroke", "#cbd5e1")
          .attr("stroke-width", 1.5);
        
        edgeGroup
          .append("text")
          .attr("x", labelX + offsetX)
          .attr("y", labelY + 2)
          .attr("text-anchor", "middle")
          .attr("fill", "#0f172a")
          .style("font-size", "12px")
          .style("font-weight", "700")
          .text(e.label);
      }
    });

    // draw nodes
    const nodeGroup = svgEl.append("g").attr("class", "nodes");
    const gNodes = nodeGroup.selectAll(".node").data(g.nodes).enter().append("g")
      .attr("class", "node")
      .style("cursor", "pointer")
      .on("click", function(event, d) {
        // Highlight the node temporarily
        d3.select(this).select("rect, polygon").style("opacity", 0.7);
        setTimeout(() => {
          d3.select(this).select("rect, polygon").style("opacity", 1);
        }, 200);
        
        // Call the callback with line number and node data if provided
        if (onNodeClick && d.lineNumber) {
          onNodeClick(d.lineNumber, d);
        }
      });

    // shapes
    gNodes.each(function (d) {
      const node = d3.select(this);
      const x = d.x - nodeWidth / 2;
      const y = d.y - nodeHeight / 2;

      if (d.type === "decision" || d.type === "condition" || d.type === "loop" || d.shape === "diamond") {
        // Diamond for decisions and loops
        const cx = d.x;
        const cy = d.y;
        const w = nodeWidth / 2 + 20;
        const h = nodeHeight / 2 + 15;
        const points = [
          [cx, cy - h],
          [cx + w, cy],
          [cx, cy + h],
          [cx - w, cy],
        ]
          .map((p) => p.join(","))
          .join(" ");
        node
          .append("polygon")
          .attr("points", points)
          .attr("fill", "#fef3c7")
          .attr("stroke", "#f59e0b")
          .attr("stroke-width", 2.5);
        
        // Wrap text if it's too long
        const text = d.label || d.text || '';
        const words = text.split(' ');
        const textElement = node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y)
          .attr("text-anchor", "middle")
          .attr("fill", "#78350f")
          .style("font-size", "12px")
          .style("font-weight", "600");
        
        if (words.length > 5) {
          const mid = Math.ceil(words.length / 2);
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "-0.4em")
            .text(words.slice(0, mid).join(' '));
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "1.2em")
            .text(words.slice(mid).join(' '));
        } else {
          textElement.text(text);
        }
      } else if (d.shape === "stadium" || d.shape === "terminal" || d.type === "start" || d.type === "end") {
        // Terminal shape (rounded rectangle/stadium) for Start/End
        node
          .append("rect")
          .attr("x", x)
          .attr("y", y)
          .attr("width", nodeWidth)
          .attr("height", nodeHeight)
          .attr("rx", nodeHeight / 2)
          .attr("ry", nodeHeight / 2)
          .attr("fill", "#dcfce7")
          .attr("stroke", "#16a34a")
          .attr("stroke-width", 2.5);

        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 5)
          .attr("text-anchor", "middle")
          .attr("fill", "#14532d")
          .style("font-size", "14px")
          .style("font-weight", "700")
          .text(d.label || d.text || '');
      } else if (d.shape === "parallelogram" || d.type === "io" || d.type === "input" || d.type === "output") {
        // Parallelogram for input/output
        const skewX = 25;
        node
          .append("polygon")
          .attr("points", [
            [x + skewX, y],
            [x + nodeWidth, y],
            [x + nodeWidth - skewX, y + nodeHeight],
            [x, y + nodeHeight],
          ]
            .map((p) => p.join(","))
            .join(" "))
          .attr("fill", "#dbeafe")
          .attr("stroke", "#0284c7")
          .attr("stroke-width", 2.5);

        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 5)
          .attr("text-anchor", "middle")
          .attr("fill", "#0c4a6e")
          .style("font-size", "12px")
          .style("font-weight", "600")
          .text(d.label || d.text || '');
      } else {
        // Rectangle for process steps
        node
          .append("rect")
          .attr("x", x)
          .attr("y", y)
          .attr("width", nodeWidth)
          .attr("height", nodeHeight)
          .attr("rx", 6)
          .attr("fill", "#f3e8ff")
          .attr("stroke", "#9333ea")
          .attr("stroke-width", 2.5);

        // Wrap text for long content
        const text = d.label || d.text || '';
        const maxChars = 40;
        const textElement = node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y)
          .attr("text-anchor", "middle")
          .attr("fill", "#581c87")
          .style("font-size", "12px")
          .style("font-weight", "600");
        
        if (text.length > maxChars) {
          const words = text.split(' ');
          const mid = Math.ceil(words.length / 2);
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "-0.3em")
            .text(words.slice(0, mid).join(' '));
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "1.2em")
            .text(words.slice(mid).join(' '));
        } else {
          textElement.text(text);
        }
      }
    });
  }, [graph, code]);

  return (
    <div style={{ width: "100%", height: "100%" }}>
      <svg ref={svgRef} style={{ display: "block", width: "100%", height: "auto" }}></svg>
    </div>
  );
}

export default SvgFlow;
